package cl.duoc.tienda.categoria.controller;
import cl.duoc.tienda.categoria.dto.*; import cl.duoc.tienda.categoria.model.*; import cl.duoc.tienda.categoria.service.*; import io.swagger.v3.oas.annotations.Operation; import io.swagger.v3.oas.annotations.tags.Tag; import jakarta.validation.Valid; import java.net.URI; import java.util.*; import org.springframework.http.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/categorias") @Tag(name="Categoria",description="CRUD de categorias") public class CategoriaController { private final CategoriaService service; public CategoriaController(CategoriaService s){service=s;} @GetMapping @Operation(summary="Listar categorias") public ResponseEntity<List<Categoria>> listar(){return ResponseEntity.ok(service.listar());} @GetMapping("/{id}") public ResponseEntity<Categoria> buscar(@PathVariable Long id){return ResponseEntity.ok(service.buscar(id));} @PostMapping public ResponseEntity<Categoria> crear(@Valid @RequestBody CategoriaRequest d){Categoria e=service.guardar(d);return ResponseEntity.created(URI.create("/categorias/"+e.getId())).body(e);} @PutMapping("/{id}") public ResponseEntity<Categoria> actualizar(@PathVariable Long id,@Valid @RequestBody CategoriaRequest d){return ResponseEntity.ok(service.actualizar(id,d));} @DeleteMapping("/{id}") public ResponseEntity<Void> eliminar(@PathVariable Long id){service.eliminar(id);return ResponseEntity.noContent().build();} }
